code.lotusscript:
Function xSDSP_xBoniComm(Byval p_Code As String, p_Contributions As Double) As Double
	' Cette fonction retourne la valeur d'une variable d'un document.

	Dim nd As NotesDocument
	Dim a_Contributions As Variant
	Dim a_Montants As Variant
	Dim i As Integer

%REM
v_Contributions := @IfError(@DbLookup(""; ""; "V_Comm1"; Prop_CommissionsRepresentant; 10); 0);
@If(@Elements(v_Contributions) = 0; @Return(0); "");
v_Montants := @IfError(@DbLookup(""; ""; "V_Comm1"; Prop_CommissionsRepresentant; 11); 0);
@If(@Elements(v_Montants) = 0; @Return(0); "");

REM {Montant supérieur à la dernière borne, retourner le dernier montant};
@If(Prop_ContribMarginalesBrutes_7 > @Subset(v_Contributions; -1); @Return(@Subset(v_Montants; -1)); "");

REM {Boucle sur le tableau des contributions};
v_Indice := 1;
@While(v_Indice < @Elements(v_Contributions) & Prop_ContribMarginalesBrutes_7 > @Subset(@Subset(v_Contributions; v_Indice); -1); v_Indice := v_Indice + 1);

REM {Extrait la valeur appropriée};
@If(v_Indice > @Elements(v_Montants); @Subset(v_Montants; -1); @Subset(@Subset(v_Montants; v_Indice); -1))
%END REM

	xSDSP_xBoniComm = 0
	Set nd = xSDSP_xndComm(p_Code, True)
	a_Contributions = xVarArray(nd, "Comm_BoniContributions")
	a_Montants = xVarArray(nd, "Comm_BoniMontants")
	If Isarray(a_Contributions) And Isarray(a_Montants) Then
		For i = 0 To Ubound(a_Contributions)
			If i > Ubound(a_Montants) Then
				Exit Function
			Else
				xSDSP_xBoniComm = a_Montants(i)
				If p_Contributions <= a_Contributions(i) Then
					Exit Function
				End If
			End If
		Next
	End If

End Function

Function xSDSP_xCommGlobaleComm(Byval p_Code As String, p_ProfitNet As Double) As Double
	' Cette fonction retourne la valeur d'une variable d'un document.

	Dim nd As NotesDocument
	Dim a_BorneSuperieure As Variant
	Dim a_MontantCommissions As Variant
	Dim i As Integer
	Dim d As Double

%REM
REM {calculer commission globale 0=standard , 1=globale};
REM {si le profit est moins que la dernière tranche, retourne le montant correspondant du tableau};
REM {si le profit est plus que la dernière tranche, calculer le profit supplémentaire};

@If(Prop_TypeCommission = "1";

@Do(
v_ProfitNet := Prop_ProfitNetPR_5;
v_BorneSuperieure := @IfError(@DbLookup(""; ""; "V_Comm1"; Prop_CommissionsRepresentant; 13); @Return(0));
v_MontantCommissions := @IfError(@DbLookup(""; ""; "V_Comm1"; Prop_CommissionsRepresentant; 14); @Return(0));
v_MontantSuplementaire := @IfError(@DbLookup(""; ""; "V_Comm1"; Prop_CommissionsRepresentant; 16); @Return(0));
v_TrancheSupplementaire := @IfError(@DbLookup(""; ""; "V_Comm1"; Prop_CommissionsRepresentant; 15); @Return(0));
n := 1;

@While(n <= @Elements(v_BorneSuperieure);
@If(v_ProfitNet <=v_BorneSuperieure[n];  @Return(v_MontantCommissions[n]);
"");
n := n + 1);

v_Supplementaire :=  (v_ProfitNet - (v_BorneSuperieure[@Elements(v_BorneSuperieure)]))  ;
v_Commission := @Integer(v_Supplementaire / v_TrancheSupplementaire);
@Return(v_Commission * v_MontantSuplementaire  + v_MontantCommissions[@Elements(v_MontantCommissions)]))
;0)
%END REM

	xSDSP_xCommGlobaleComm = 0
	Set nd = xSDSP_xndComm(p_Code, True)
	If xVar(nd, "Comm_CalculCommissions", "") = "1" Then
		a_BorneSuperieure = xVarArray(nd, "Comm_BorneSuperieure")
		a_MontantCommissions = xVarArray(nd, "Comm_MontantCommissions")
		If Isarray(a_BorneSuperieure) And Isarray(a_MontantCommissions) Then
			For i = 0 To Ubound(a_BorneSuperieure)
				If i > Ubound(a_MontantCommissions) Then
					Exit Function
				Else
					xSDSP_xCommGlobaleComm = a_MontantCommissions(i)
					If p_ProfitNet <= a_BorneSuperieure(i) Then
						Exit Function
					End If
				End If
			Next

			d = p_ProfitNet - a_BorneSuperieure(Ubound(a_BorneSuperieure))
			d = Cint(d / xVar(nd, "Comm_TrancheSupplementaire", 1))
			xSDSP_xCommGlobaleComm = xSDSP_xCommGlobaleComm + (d * xVar(nd, "Comm_MontantSupplementaire", 0))
		End If
	End If
End Function

