REM {Extraire l'ensemble des statuts disponibles};
result:=@DbLookup(""; ""; "V_Tabl20"; DB_TableStatuts; 6);

REM {Enlever les statuts impossible en fonction du statut actuel};
REM {DÉSACTIVATION DE CETTE PARTIE POUR LE MOMENT
statAct :=@Right(DB_StatutActuel;2);
temp := "";
statCur := "";
@For(n := 1; n <= @Elements(result); n := n + 1;@Do(
 statCur:=@Right(result[n];2);
 @If((statCur=statAct)
 | (statCur="05")
 | (statCur="12" & statAct  != "25")
 | (statCur="09" & statAct  < "10")
 | (statCur="25" & statAct  >= "10")
 | (statCur="45" & statAct  != "25")
 | (statCur="94" & statAct  >= "90")
 | (statCur="95" & statAct  != "45");
  ""; @Set("temp";temp:result[n]))));
@If(@IsError(temp);"";@Trim(temp))};

@If(@IsError(result);"";result)

